[5] log_data_to_marketing_crm(customer_id='CUST98765', data={'full_address': '456 Nguyen Hue, Quan Binh Thanh, HCMC', 'phone': '0901234567'}) -> {'status': 'logged'}
[6] notify_logistics_of_address_change(order_id='VN54321', new_address='456 Nguyen Hue, Quan Binh Thanh, HCMC') -> {'status': 'notification_sent'}
[7] send_customer_confirmation_email(customer_id='CUST98765', message='Your shipping address for order VN54321 has been updated.') -> {'status': 'email_sent'}

