[2] get_customer_preferred_refund_method(customer_id='CUST44556') -> {'method': 'BANK_TRANSFER', 'account_number': '1234567890', 'bank_name': 'Techcombank', 'recipient_name': 'Tran Van Linh'}
[3] verify_bank_account_ownership(customer_id='CUST44556', account_number='1234567890') -> {'status': 'verified', 'owner_matches': True}
